'use strict';
/* public/js/72-twisters.js -- twisters: schedule, pull/suck-up/ragdoll, visuals, sound. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- twisters ---------- */
/* Twisters form out on the lake during the day and wander for a minute or two.
   Every camper sees the same twisters without the server sending anything: they're worked out from the shared camp
   clock and a fixed random seed. The lake is split into TW_CELL-sized squares, and in every TW_WIN window each
   square has a TW_CHANCE chance of growing one. Only the squares around you are checked, so wherever you are,
   twisters can show up nearby.
   Get within TW_PULL_R and the wind drags you in, gently at first and steeply harder as you get close (a real
   tornado is "nothing, nothing, then everything") - walking against it is enough at the rim, sprinting still wins
   at mid-range, and near the core no speed saves you. Get within TW_SUCK_R and it lifts you clean off your feet and
   spins you up the funnel for a beat before flinging you out (TW_DMG health, scaled by strength) into a tumbling
   ragdoll fall; you land, skid, lie there, then get back up. None of this touches the twister's own path - it's
   still a pure function of shared time + seed, so every camper sees it in the same place.
   They weaken and fall apart near camp, die down at night, and can't reach you while you're down in a hole deeper
   than 4 feet. Type "twister" in game to summon a test one that only you can see. */
const TW_CELL=200,TW_WIN=120000,TW_CHANCE=0.3,TW_SPEED=3.2;
const TW_PULL_R=25;         // outer edge of the wind - widened now the rim is gentle instead of a hard line
const TW_SUCK_R=6;          // inside this you're lifted off your feet instead of just pulled (both x tw.s)
const TW_PULL_POW=2.4;      // pull ramps with (1-d/pr)^POW between the two radii: flat near the rim, steep near the core
const TW_PULL_MAX=11;       // pull speed (m/s) right at the mouth of the suck radius, before strength scaling
const TW_SPIN_MAX=7.5;      // tangential (swirl) speed at that same point - drags you around the funnel, not just in
const TW_SUCK_TIME=1.1;     // seconds spent spiralling upward before the throw
const TW_SUCK_RISE=10;      // how high (m) you're lifted during the suck-up
const TW_DOWN_TIME=1.4;     // seconds lying flat after landing
const TW_GETUP_TIME=0.4;    // quick stand-up transition (down+getup ~= the 1.5-2s JT asked for)
const TW_DMG=30,TW_SAFE_DEPTH=1.2;
const TW_LIVE=new Map();   // id -> twister currently near you: {x,z,s (strength 0-1), ...}
let twSpawned=[],twCool=0,twWind=null;   // twSpawned: twisters made with the console (see ENV below)
/* twSt: what a twister is currently doing to YOU (0 free, 1 sucked up, 2 airborne/tumbling, 3 down, 4 getting up).
   Purely local/per-client - like the old kx/kz knockback, it never touches the twister's own state, so it can't
   break determinism between players. twStT times the current state; the rest are the grabbing twister's details,
   kept around in case it despawns mid-grab (e.g. a console twister's lifetime runs out while it has you). */
let twSt=0,twStT=0,twGrab=null,twCenter={x:0,z:0},twStrength=0,twSuckR0=1,twSpiralA=0,twRagX=0,twRagY=0,twRagZ=0,twDbgPull=0;
function twStateName(){return['free','sucked','airborne','down','gettingup'][twSt]}
// Absolute shared time for hazard schedules. CLK.off is set by the host's clock changes as (time of day - now), a huge
// negative number, so Date.now()+CLK.off collapsed to "time of day" and the natural twister/landslide schedule
// repeated every in-game day. Wrapping the offset keeps the same time of day but a real, ever-increasing clock.
function twNow(){return Date.now()+wrapT(CLK.off)}
/* the twister (if any) that square (ci,cj) grows in window k: where it starts, which way it heads, how long it lasts */
function twPlan(ci,cj,k){
  const r=mulberry32((((ci+64)*131+(cj+64))*2654435761^(k*40503))>>>0);r();
  if(r()>TW_CHANCE)return null;
  return{id:ci+','+cj+','+k,x0:(ci+r())*TW_CELL,z0:(cj+r())*TW_CELL,a:r()*Math.PI*2,ph:r()*6.28,t0:k*TW_WIN+r()*20000,life:80+r()*30};
}
/* where a planned twister is at time T, and how strong it is (0 = not there) */
function twAt(pl,T){
  const e=(T-pl.t0)/1000;if(e<0||e>pl.life)return null;
  const x=pl.x0+Math.cos(pl.a)*TW_SPEED*e+Math.sin(e*0.11+pl.ph)*14,z=pl.z0+Math.sin(pl.a)*TW_SPEED*e+Math.cos(e*0.09+pl.ph)*14;
  let s=sm(e/10)*sm((pl.life-e)/10);                           // grows for 10 s, dies down over the last 10 s
  s*=clamp((campDist(x,z)-15)/35,0,1);                         // falls apart as it nears camp
  if(!pl.forced)s*=1-nightF();                                 // only during the day (console-made ones ignore this)
  if(Math.max(Math.abs(x),Math.abs(z))>EDGE-10)s=0;           // off the edge of the lake
  return{x,z,s,e};
}
/* a twister made on demand (console / ENV). forced: it ignores the time of day, so testers can spawn one at night */
function addTwister(x,z,a){twSpawned.push({id:'spawn'+Math.random().toString(36).slice(2,8),x0:x,z0:z,a,ph:(x*7+z*3)%6.28,t0:twNow(),life:75,forced:true})}

/* looks: three swirling funnel layers + a dust skirt + flying debris. The funnel bends with a small vertex-shader
   tweak (uTime), and a few pooled visuals are reused so twisters coming and going never allocate new meshes. */
const twU={uTime:{value:0}};
const twTex=(()=>{const c=document.createElement('canvas');c.width=64;c.height=256;const x=c.getContext('2d');
  x.fillStyle='rgba(255,255,255,0.55)';x.fillRect(0,0,64,256);   // solid dusty base so the funnel reads from a distance
  for(let i=0;i<46;i++){x.strokeStyle=`rgba(255,255,255,${0.15+Math.random()*0.55})`;x.lineWidth=2+Math.random()*6;const y=Math.random()*256;x.beginPath();x.moveTo(-10,y);x.lineTo(74,y-40-Math.random()*40);x.stroke()}
  const t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;return t})();
function twMat(color,op){
  const m=new T.MeshBasicMaterial({color,map:twTex,transparent:true,opacity:op,depthWrite:false,side:T.DoubleSide});
  m.onBeforeCompile=sh=>{sh.uniforms.uTime=twU.uTime;
    sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nuniform float uTime;').replace('#include <begin_vertex>',
      '#include <begin_vertex>\nfloat hh=position.y+15.0;transformed.x+=sin(uTime*1.1+hh*0.09)*hh*0.09;transformed.z+=cos(uTime*0.8+hh*0.07)*hh*0.07;')};
  m.userData.op=op;return m;
}
const TW_FUNNEL=new T.CylinderGeometry(7.5,1.1,30,20,14,true);TW_FUNNEL.translate(0,15,0);
const TW_SKIRT=new T.CylinderGeometry(3.2,6.5,3.2,20,1,true);TW_SKIRT.translate(0,1.2,0);
const TW_DEBRIS_N=70;
const twPool=[];
for(let i=0;i<3;i++){
  const g=new T.Group();g.visible=false;scene.add(g);
  const layers=[[1,0xb8905e,0.7],[0.78,0xd2ad7c,0.6],[0.55,0x8e6a44,0.75]].map(([sc,c,op])=>{const m=new T.Mesh(TW_FUNNEL,twMat(c,op));m.scale.set(sc,1,sc);m.renderOrder=2;g.add(m);return m});
  const skirt=new T.Mesh(TW_SKIRT,twMat(0xc99a66,0.5));skirt.renderOrder=2;g.add(skirt);
  const deb=new T.InstancedMesh(new T.BoxGeometry(0.28,0.12,0.2),M(0x7a5a3a),TW_DEBRIS_N);deb.frustumCulled=false;deb.instanceMatrix.setUsage(T.DynamicDrawUsage);g.add(deb);
  const seeds=Array.from({length:TW_DEBRIS_N},()=>({a:Math.random()*6.28,h:Math.random(),sp:1.5+Math.random()*2.5}));
  twPool.push({g,layers,skirt,deb,seeds,used:null});
}
function twVisual(tw,dt){
  let v=twPool.find(p=>p.used===tw.id)||twPool.find(p=>!p.used);if(!v)return;v.used=tw.id;
  const g=v.g;g.visible=true;g.position.set(tw.x,groundAt(tw.x,tw.z)-0.3,tw.z);
  const w=0.35+0.65*tw.s;g.scale.set(w,0.5+0.5*tw.s,w);
  v.layers.forEach((m,i)=>{m.rotation.y+=dt*(3+i*1.7);m.material.opacity=m.material.userData.op*tw.s});
  v.skirt.rotation.y-=dt*4;v.skirt.material.opacity=v.skirt.material.userData.op*tw.s;
  for(let i=0;i<TW_DEBRIS_N;i++){const d=v.seeds[i];d.a+=dt*d.sp*(2.2-d.h);d.h+=dt*0.12;if(d.h>1)d.h=0;
    const r=1.2+d.h*7,y=d.h*26;dummy.position.set(Math.cos(d.a)*r,y,Math.sin(d.a)*r);dummy.rotation.set(d.a*3,d.a*2,0);dummy.scale.setScalar(tw.s);dummy.updateMatrix();v.deb.setMatrixAt(i,dummy.matrix)}
  v.deb.instanceMatrix.needsUpdate=true;
}
function twSound(level){
  if(!AC)return;
  if(!twWind){const src=AC.createBufferSource();src.buffer=noiseBuf;src.loop=true;const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=380;twWind=AC.createGain();twWind.gain.value=0;src.connect(f).connect(twWind).connect(master);src.start()}
  twWind.gain.setTargetAtTime(level*0.6,AC.currentTime,0.3);
}

function updateTwisters(dt){
  twU.uTime.value+=dt;twCool=Math.max(0,twCool-dt);
  const T0=twNow(),k=Math.floor(T0/TW_WIN),fx=S.started?P.x:0,fz=S.started?P.z:12;
  const ci=Math.floor(fx/TW_CELL),cj=Math.floor(fz/TW_CELL),seen=new Set();
  // which twisters are around right now: this window's and the last one's (a twister can run past its window)
  const plans=[];
  for(let i=ci-1;i<=ci+1;i++)for(let j=cj-1;j<=cj+1;j++)for(const kk of[k-1,k]){const pl=twPlan(i,j,kk);if(pl)plans.push(pl)}
  plans.push(...twSpawned);
  let nearest=1e9,loud=0;
  for(const pl of plans){
    const at=twAt(pl,T0);if(!at||at.s<=0.01){if(pl.forced&&(!at||at.e>pl.life-0.1))twSpawned=twSpawned.filter(t=>t!==pl);continue}
    const d=Math.hypot(at.x-fx,at.z-fz);if(d>260)continue;
    let tw=TW_LIVE.get(pl.id);if(!tw){tw={id:pl.id,warned:false};TW_LIVE.set(pl.id,tw)}
    Object.assign(tw,at);seen.add(pl.id);nearest=Math.min(nearest,d);loud=Math.max(loud,at.s*clamp(1-d/140,0,1)**2);
    if(S.started&&!inTent()&&!tw.warned&&at.s>0.3&&d<120){tw.warned=true;logEv('twWarn',{x:+P.x.toFixed(1),z:+P.z.toFixed(1),twx:+at.x.toFixed(1),twz:+at.z.toFixed(1),dist:+d.toFixed(1),dir:compass(at.x-P.x,at.z-P.z)});toast(`Twister to the ${compass(at.x-P.x,at.z-P.z)}! Get out of its way, or get down in a deep hole.`,'bad',6000)}
    twVisual(tw,dt);
    if(S.started&&!S.ko)twPush(tw,d,dt);
  }
  for(const[id]of TW_LIVE)if(!seen.has(id)){TW_LIVE.delete(id);const v=twPool.find(p=>p.used===id);if(v){v.used=null;v.g.visible=false}}
  twSound(loud);
  // camera shake the closer you are
  if(S.started&&!inTent()&&nearest<40){const a=clamp(1-nearest/40,0,1)*0.12;camera.position.x+=(Math.random()-0.5)*a;camera.position.y+=(Math.random()-0.5)*a}
}
/* the wind: gentle at TW_PULL_R, steep near TW_SUCK_R (real tornadoes don't ramp up smoothly the whole way - you
   feel almost nothing, then suddenly you're fighting hard), plus a swirl so it drags you around the funnel, not
   just in. Cross into TW_SUCK_R and twStart() takes over instead of a plain shove. */
function twPush(tw,d,dt){
  if(inTent())return;   // inside a tent: sheltered, even though your x/z is still technically "out there"
  if(holeDepthHere()>TW_SAFE_DEPTH)return;   // down in a deep hole: the wind goes over your head
  if(twSt)return;                            // already caught by a twister (suck/air/down/up) - let that play out
  const pr=TW_PULL_R*tw.s;if(d>pr||d<0.01)return;
  const sr=Math.max(TW_SUCK_R*tw.s,0.4);
  if(d<sr){if(twCool<=0)twStart(tw,d);return}
  const norm=clamp(1-(d-sr)/(pr-sr),0,1),f=Math.pow(norm,TW_PULL_POW);
  const dx=(tw.x-P.x)/d,dz=(tw.z-P.z)/d;
  const pull=TW_PULL_MAX*tw.s*f,spin=TW_SPIN_MAX*tw.s*f;      // walking (4.3) beats it near the rim, sprint (7.2) near mid-range
  twDbgPull=pull;
  P.x=clamp(P.x+(dx*pull-dz*spin)*dt,-HALF+3,HALF-3);P.z=clamp(P.z+(dz*pull+dx*spin)*dt,-HALF+3,HALF-3);
}
/* sucked up: lifts you off the ground and spirals you in toward the core for TW_SUCK_TIME before the throw.
   No movement control here - the wind has you. Keeps a live ref to the twister (twGrab) but falls back to the last
   known spot (twCenter/twStrength) if it despawns mid-grab, so a twister expiring never leaves you stuck. */
function twStart(tw,d){
  twSt=1;twStT=0;twGrab=tw.id;twCenter={x:tw.x,z:tw.z};twStrength=tw.s;twSuckR0=Math.max(d,0.6);
  twSpiralA=Math.atan2(P.z-tw.z,P.x-tw.x);P.moving=false;P.anim=0;digHeld=false;
  logEv('twSuckUp',{x:+P.x.toFixed(1),z:+P.z.toFixed(1),twx:+tw.x.toFixed(1),twz:+tw.z.toFixed(1),s:+tw.s.toFixed(2)});
  if(!S.ko)toast('The wind has you!','bad',2000);
}
/* the throw: flings you outward and hurts you same as before, then hands off to the airborne ragdoll tumble */
function twThrow(tw){
  twCool=4;                                                    // a few seconds before it can grab you again
  const out=Math.random()*Math.PI*2,sp=16+tw.s*6;
  P.kx=Math.cos(out)*sp;P.kz=Math.sin(out)*sp;P.vy=10+tw.s*3;P.grounded=false;
  twRagX=(Math.random()*2-1)*11;twRagY=(Math.random()*2-1)*7;twRagZ=(Math.random()*2-1)*9;  // mixed axes: a tumble, not a spin
  twSt=2;twStT=0;digHeld=false;sfx.hiss();
  const dmg=Math.round(TW_DMG*tw.s);
  logEv('twThrow',{x:+P.x.toFixed(1),z:+P.z.toFixed(1),twx:+tw.x.toFixed(1),twz:+tw.z.toFixed(1),dmg});
  hurt(dmg,'Twister','A twister picked you up and threw you across the lake.');
  if(!S.ko)toast(`The twister threw you! -${dmg} health`,'bad',3000);
}
/* landing: keep a little of the throw's speed as a skid instead of stopping dead, then lie there */
function twLand(){P.grounded=true;twSt=3;twStT=0;P.anim=3;P.kx*=0.4;P.kz*=0.4}
/* drives states 1-4 every frame, in place of the normal movement/knockback code in updatePlayer (which it replaces
   while a twister has you). If S.ko fires mid-sequence (the throw's damage, a lizard, whatever) knockOut() clears
   twSt itself, so control falls straight back to the normal S.ko handling next frame - no state to get stuck in. */
function twStep(dt){
  twStT+=dt;
  if(twSt===1){                                                 // spiralling up the funnel
    const tw=TW_LIVE.get(twGrab),cx=tw?tw.x:twCenter.x,cz=tw?tw.z:twCenter.z;
    const u=clamp(twStT/TW_SUCK_TIME,0,1);
    twSpiralA+=dt*(4+10*u);const r=lerp(twSuckR0,0.6,u);
    P.x=clamp(cx+Math.cos(twSpiralA)*r,-HALF+3,HALF-3);P.z=clamp(cz+Math.sin(twSpiralA)*r,-HALF+3,HALF-3);
    P.y=groundAt(P.x,P.z)+TW_SUCK_RISE*sm(u);P.grounded=false;
    me.g.position.set(P.x,P.y,P.z);me.g.rotation.y=twSpiralA+Math.PI/2;me.g.rotation.x=lerp(me.g.rotation.x,0,dt*4);me.g.rotation.z+=dt*10;
    if(twStT>=TW_SUCK_TIME)twThrow(tw||{s:twStrength});
  }else if(twSt===2){                                           // thrown - tumbling flight
    P.x=clamp(P.x+P.kx*dt,-HALF+3,HALF-3);P.z=clamp(P.z+P.kz*dt,-HALF+3,HALF-3);
    P.vy-=16*dt;P.y+=P.vy*dt;
    me.g.rotation.x+=dt*twRagX;me.g.rotation.y+=dt*twRagY;me.g.rotation.z+=dt*twRagZ;
    const g=groundAt(P.x,P.z);if(P.y<=g){P.y=g;P.vy=0;twLand()}
    me.g.position.set(P.x,P.y,P.z);
  }else if(twSt===3){                                           // down - skid dies out, then lie still
    const f=Math.exp(-dt*5);P.kx*=f;P.kz*=f;
    if(Math.hypot(P.kx,P.kz)>0.05){P.x=clamp(P.x+P.kx*dt,-HALF+3,HALF-3);P.z=clamp(P.z+P.kz*dt,-HALF+3,HALF-3);P.y=groundAt(P.x,P.z)}
    animPerson(me,3,dt);me.g.rotation.z=lerp(me.g.rotation.z,0,Math.min(1,dt*6));me.g.position.set(P.x,P.y,P.z);
    if(twStT>=TW_DOWN_TIME){twSt=4;twStT=0}
  }else if(twSt===4){                                           // getting up
    const u=clamp(twStT/TW_GETUP_TIME,0,1);
    me.g.rotation.x=lerp(-Math.PI/2,0,u);me.g.rotation.z=lerp(me.g.rotation.z,0,Math.min(1,dt*8));
    me.g.position.set(P.x,P.y,P.z);
    if(u>=1){twSt=0;P.kx=P.kz=0;P.anim=0;me.g.rotation.set(0,me.g.rotation.y,0)}
  }
}

